int runTrackPreview551(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;try{auto require=[](bool value,const char* why){if(!value)throw std::runtime_error(why);};auto source=std::make_shared<AudioData>();source->rate=44100;source->path=LibraryStore::root().getChildFile("New Track.wav").getFullPathName();source->buffer.setSize(1,44100*20);for(int n=0;n<source->buffer.getNumSamples();++n)source->buffer.setSample(0,n,.2f*std::sin(n*.04));source->buildWaveformPeaks();
 Processor p(false);p.autoSave=false;p.audio=source;p.sourceBpm=120;p.split(4,false);p.trackStemsEnabled=false;p.prepareToPlay(44100,256);p.setPlaybackMode(4);auto session=std::atomic_load(&p.trackPlayer.session);require(session&&session->audio==source&&!p.trackGridReady,"new track publishes estimated-grid playback before full analysis");TrackPanel panel(p);for(int width:{620,1100}){panel.setSize(width,600);panel.sync();require(panel.analysisBar551.isVisible()&&!panel.analysisBar551.getBounds().intersects(panel.gridMode.getBounds())&&!panel.analysisBar551.getBounds().intersects(panel.info.getBounds()),"visible analysis bar has reserved space in compact and wide layouts");}juce::AudioBuffer<float> out(2,256);juce::MidiBuffer midi;double heard=0;auto start=juce::Time::getMillisecondCounterHiRes();while(heard<.02&&juce::Time::getMillisecondCounterHiRes()-start<2500){p.serviceTrack();p.processBlock(out,midi);heard=out.getRMSLevel(0,0,256);juce::Thread::sleep(6);}require(heard>.02&&!p.trackGridReady,"audio plays while full-model analysis remains pending");
 auto second=std::make_shared<AudioData>();second->rate=source->rate;second->path=LibraryStore::root().getChildFile("Next Track.wav").getFullPathName();second->buffer.makeCopyOf(source->buffer);p.audio=second;p.trackPreparedAudio.reset();p.trackGridReady=p.trackGridEdited=false;p.serviceTrack();session=std::atomic_load(&p.trackPlayer.session);require(session&&session->audio==second&&!p.trackGridReady,"switching uncached tracks replaces the session without waiting");
 auto ready=std::make_shared<TrackGrid>();ready->bpm=123;ready->detector="Beat This full final0";ready->anchors={{1000,0},{44100*10,20}};p.trackGrid=*ready;p.trackGridReady=p.trackGridEdited=true;p.serviceTrack();session=std::atomic_load(&p.trackPlayer.session);require(session&&session->audio==second&&session->grid.bpm==123,"ready grid updates the existing source session");p.unload();std::cout<<"New-track preview publishes and plays before full analysis, uncached switching and ready-grid handoff passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<"TrackPreview551: "<<error.what()<<"\n";return 2551;}}
